"use client";

import { Box, FileUpload, Icon, useFileUploadContext } from "@chakra-ui/react"
import { LuUpload } from "react-icons/lu"

const MAX_FILES = 3

const ConditionalDropzone = () => {
  const fileUpload = useFileUploadContext()
  const acceptedFiles = fileUpload.acceptedFiles

  if (acceptedFiles.length >= MAX_FILES) {
    return null
  }

  return (
    <FileUpload.Dropzone>
      <Icon size="md" color="fg.muted">
        <LuUpload />
      </Icon>
      <FileUpload.DropzoneContent>
        <Box>Drag and drop files here</Box>
        <Box color="fg.muted">
          {MAX_FILES - acceptedFiles.length} more file
          {MAX_FILES - acceptedFiles.length !== 1 ? "s" : ""} allowed
        </Box>
      </FileUpload.DropzoneContent>
    </FileUpload.Dropzone>
  )
}

export const FileUploadWithConditionalDropzone = () => {
  return (
    <FileUpload.Root maxW="xl" alignItems="stretch" maxFiles={MAX_FILES}>
      <FileUpload.HiddenInput />
      <ConditionalDropzone />
      <FileUpload.List clearable />
    </FileUpload.Root>
  )
}

"use client";

import { Button, Field, FileUpload } from "@chakra-ui/react"
import { standardSchemaResolver } from "@hookform/resolvers/standard-schema"
import { Controller, useForm } from "react-hook-form"
import { HiUpload } from "react-icons/hi"
import { z } from "zod"

const formSchema = z.object({
  images: z.array(z.instanceof(File)).min(1, "At least one image is required"),
})

type FormValues = z.infer<typeof formSchema>

export const FileUploadWithHookForm = () => {
  const {
    control,
    handleSubmit,
    formState: { errors },
  } = useForm<FormValues>({
    resolver: standardSchemaResolver(formSchema),
    defaultValues: {
      images: [],
    },
  })

  const onSubmit = handleSubmit((data) => console.log(data))

  return (
    <form onSubmit={onSubmit}>
      <Controller
        control={control}
        name="images"
        render={({ field }) => (
          <Field.Root invalid={!!errors.images}>
            <Field.Label>Images</Field.Label>
            <FileUpload.Root
              name={field.name}
              onFileChange={(e) => {
                field.onChange(e.acceptedFiles)
              }}
            >
              <FileUpload.HiddenInput />
              <FileUpload.Trigger asChild onBlur={() => field.onBlur()}>
                <Button variant="outline" size="sm">
                  <HiUpload /> Upload file
                </Button>
              </FileUpload.Trigger>

              <FileUpload.List />
            </FileUpload.Root>
            <Field.ErrorText>{errors.images?.message}</Field.ErrorText>
          </Field.Root>
        )}
      />

      <Button type="submit" size="sm" mt="4">
        Submit
      </Button>
    </form>
  )
}

